								    "pciephy");
	if (IS_ERR(imx6_pcie->pciephy_reset)) {
		dev_err(dev, "Failed to get PCIEPHY reset control\n");
		return PTR_ERR(imx6_pcie->pciephy_reset);
	}

	imx6_pcie->apps_reset = devm_reset_control_get_exclusive(dev,
